<div class="table-responsive mt-4"><table class="table table-bordered weekly-timetable"><caption>{{ $caption??'Weekly class timetable' }}</caption><thead><tr><th>Time</th>@foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day)<th>{{ $day }}</th>@endforeach</tr></thead><tbody>@for($hour=7;$hour<21;$hour++)<tr><th>{{ sprintf('%02d:00',$hour) }}</th>@foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day)<td class="week-cell" data-day="{{ $day }}" data-time="{{ sprintf('%02d:00',$hour) }}">@foreach($calendar->filter(fn($m)=>$m->day===$day && substr($m->start_time,0,5)<sprintf('%02d:00',$hour+1) && substr($m->end_time,0,5)>sprintf('%02d:00',$hour)) as $meeting)<div class="timetable-meeting" @isset($meeting->choice_id) data-choice="{{ $meeting->choice_id }}" @endisset><strong>{{ $meeting->code }}</strong><span class="d-block">{{ substr($meeting->start_time,0,5) }}–{{ substr($meeting->end_time,0,5) }}</span><span class="d-block">{{ $meeting->room }}</span></div>@endforeach</td>@endforeach</tr>@endfor</tbody></table></div>
